CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE IF NOT EXISTS venues(id uuid PRIMARY KEY, name text NOT NULL, domain text NOT NULL DEFAULT '', logo_url text NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS customers(id uuid PRIMARY KEY, venue_id uuid NOT NULL REFERENCES venues, name text NOT NULL, email text, member boolean NOT NULL, balance_minor bigint NOT NULL DEFAULT 0 CHECK(balance_minor >= 0), UNIQUE(venue_id,id));
CREATE TABLE IF NOT EXISTS stations(id text NOT NULL, venue_id uuid NOT NULL REFERENCES venues, zone text NOT NULL CHECK(zone IN ('Standard','VIP','Console')), hourly_minor bigint NOT NULL CHECK(hourly_minor>0), state text NOT NULL DEFAULT 'Available', PRIMARY KEY(venue_id,id));
CREATE TABLE IF NOT EXISTS sessions(id uuid PRIMARY KEY, venue_id uuid NOT NULL REFERENCES venues, station_id text NOT NULL, customer_id uuid NOT NULL, started_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, rate_minor bigint NOT NULL, reserved_minor bigint NOT NULL CHECK(reserved_minor>0), paused_at timestamptz, paused_seconds bigint NOT NULL DEFAULT 0, ended_at timestamptz, charge_minor bigint, FOREIGN KEY(venue_id,station_id) REFERENCES stations(venue_id,id), FOREIGN KEY(venue_id,customer_id) REFERENCES customers(venue_id,id));
CREATE UNIQUE INDEX IF NOT EXISTS one_active_station ON sessions(venue_id,station_id) WHERE ended_at IS NULL;
CREATE TABLE IF NOT EXISTS ledger(id uuid PRIMARY KEY, venue_id uuid NOT NULL REFERENCES venues, customer_id uuid NOT NULL, kind text NOT NULL, amount_minor bigint NOT NULL, reference text NOT NULL, actor text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(venue_id,customer_id) REFERENCES customers(venue_id,id), UNIQUE(venue_id,reference));
CREATE TABLE IF NOT EXISTS commands(venue_id uuid NOT NULL REFERENCES venues, key text NOT NULL, fingerprint text NOT NULL, response jsonb NOT NULL, PRIMARY KEY(venue_id,key));
CREATE TABLE IF NOT EXISTS reservations(id uuid PRIMARY KEY, venue_id uuid NOT NULL REFERENCES venues, customer_id uuid NOT NULL, status text NOT NULL CHECK(status IN ('PendingVenue','Confirmed','Cancelled','NoShow')), deposit_minor bigint NOT NULL DEFAULT 0, FOREIGN KEY(venue_id,customer_id) REFERENCES customers(venue_id,id));
CREATE TABLE IF NOT EXISTS reservation_seats(reservation_id uuid NOT NULL REFERENCES reservations, venue_id uuid NOT NULL, station_id text NOT NULL, booking_window tstzrange NOT NULL, active boolean NOT NULL DEFAULT true, PRIMARY KEY(reservation_id,station_id), FOREIGN KEY(venue_id,station_id) REFERENCES stations(venue_id,id), EXCLUDE USING gist(venue_id WITH =, station_id WITH =, booking_window WITH &&) WHERE(active));
CREATE TABLE IF NOT EXISTS products(id uuid PRIMARY KEY, venue_id uuid NOT NULL REFERENCES venues, name text NOT NULL, price_minor bigint NOT NULL CHECK(price_minor>0), stock integer NOT NULL CHECK(stock>=0), UNIQUE(venue_id,id));
CREATE TABLE IF NOT EXISTS orders(id uuid PRIMARY KEY, venue_id uuid NOT NULL REFERENCES venues, customer_id uuid NOT NULL, station_id text NOT NULL, product_id uuid NOT NULL, quantity integer NOT NULL CHECK(quantity>0), total_minor bigint NOT NULL, status text NOT NULL DEFAULT 'Pending', created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(venue_id,customer_id) REFERENCES customers(venue_id,id), FOREIGN KEY(venue_id,station_id) REFERENCES stations(venue_id,id), FOREIGN KEY(venue_id,product_id) REFERENCES products(venue_id,id));
CREATE TABLE IF NOT EXISTS audit(id bigserial PRIMARY KEY, venue_id uuid NOT NULL REFERENCES venues, actor text NOT NULL, action text NOT NULL, detail jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS outbox(id uuid PRIMARY KEY, venue_id uuid NOT NULL REFERENCES venues, kind text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), acknowledged_at timestamptz);
CREATE TABLE IF NOT EXISTS inbox(venue_id uuid NOT NULL REFERENCES venues, event_id uuid NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(venue_id,event_id));
CREATE TABLE IF NOT EXISTS devices(id uuid PRIMARY KEY, venue_id uuid NOT NULL REFERENCES venues, station_id text NOT NULL, certificate_thumbprint text NOT NULL UNIQUE, revoked boolean NOT NULL DEFAULT false, last_seen_at timestamptz, FOREIGN KEY(venue_id,station_id) REFERENCES stations(venue_id,id));
CREATE TABLE IF NOT EXISTS shifts(id uuid PRIMARY KEY,venue_id uuid NOT NULL REFERENCES venues,actor text NOT NULL,opened_at timestamptz NOT NULL DEFAULT now(),closed_at timestamptz,expected_minor bigint,counted_minor bigint,reason text);
